test_structure.template:
describe('ComponentName', () => {
  beforeEach(() => {
    // Arrange: set up common test state
  });

  afterEach(() => {
    jest.clearAllMocks();
  });

  test('should do something specific', () => {
    // Act
    const result = doSomething();
    // Assert
    expect(result).toBe(expected);
  });
});

describe('AsyncService', () => {
  test('should handle promise resolution', async () => {
    expect.assertions(1);
    const result = await service.method();
    expect(result).toBe(expected);
  });
});

pattern.template:
test('async operation succeeds', async () => {
  expect.assertions(1);
  const result = await asyncFunction();
  expect(result).toBe(expected);
});

pattern.error_template:
test('async operation fails', async () => {
  expect.assertions(1);
  await expect(asyncFunction()).rejects.toThrow('Error message');
});

pattern.template:
test('callback test', (done) => {
  expect.assertions(1);
  asyncOperation((result) => {
    try {
      expect(result).toBe(true);
      done();
    } catch (err) {
      done.fail(err);
    }
  });
});

timer_mocking.template:
test('executes callback after delay', () => {
  jest.useFakeTimers();
  const callback = jest.fn();

  setTimeout(callback, 1000);
  expect(callback).not.toHaveBeenCalled();

  jest.advanceTimersByTime(1000);
  expect(callback).toHaveBeenCalledTimes(1);
});

pattern.template:
test.each([
  [1, 1, 2],
  [1, 2, 3],
  [2, 1, 3],
])('add(%s, %s) returns %s', (a, b, expected) => {
  expect(a + b).toBe(expected);
});

test.each`
  a    | b    | expected
  ${1} | ${1} | ${2}
  ${1} | ${2} | ${3}
  ${2} | ${1} | ${3}
`('returns $expected when $a + $b', ({ a, b, expected }) => {
  expect(a + b).toBe(expected);
});

describe.each([
  ['mobile', 375],
  ['tablet', 768],
  ['desktop', 1024],
])('on %s (%spx)', (device, width) => {
  test('renders correctly', () => {
    // test with device/width context
  });
});

asynchronous.pattern:
try {
  await asyncFunction();
  fail('Should have thrown');
} catch (error) {
  expect(error.message).toBe('expected');
  expect(error.code).toBe('ERR_SPECIFIC');
}

performance_testing.pattern:
const start = performance.now();
await operation();
const duration = performance.now() - start;
expect(duration).toBeLessThan(1000); // milliseconds

const initialMemory = process.memoryUsage().heapUsed;
await operation();
const finalMemory = process.memoryUsage().heapUsed;
expect(finalMemory - initialMemory).toBeLessThan(threshold);

